function wordGroups(words) {
  const key = (w) => [...w].sort().join('');
  const groups = [];
  for (const word of words) {
    const group = groups.find((g) => key(g[0]) === key(word));
    if (group) group.push(word); else groups.push([word]);
  }
  for (const g of groups) g.sort();
  return groups.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

function wordGroups(words) {
  const groups = new Map();
  for (const word of words) {
    const key = [...word].sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(word);
  }
  const result = [...groups.values()].map((g) => g.sort());
  return result.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}
